insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes when resources are limited, as described in a student guide in a introductory student forum context.','The author suggests that practice and feedback are unrelated.','The author believes practice works best if learners are told what they did wrong.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The new system was adopted not because it was cheaper, but because it made the process more transparent under careful supervision, as described in a pilot study in a coastal research briefing context.','The new system was rejected because it was not transparent.','The process became less transparent after the new system was adopted.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was adopted mainly because it reduced costs.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Even though the experiment was small, its results raised important questions for future research after initial trials, as described in a professional workshop in a urban research briefing context.','Future research became unnecessary after the experiment.','The results were ignored because the experiment was not small.','The experiment was too large to raise useful questions.','Despite its limited size, the experiment produced results that future studies should examine.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction in schools, as described in a policy review in a northern research briefing context.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage says convenience always guarantees satisfaction.','The passage denies that convenience affects service use.','The passage argues that inconvenient services attract the most users.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The committee approved the plan only after several risks had been identified and addressed for adult learners, as described in a classroom discussion in a southern research briefing context.','The plan was accepted although no risks were identified.','The plan was accepted once the committee had dealt with the risks it found.','The committee rejected the plan because all risks were addressed.','The committee approved the plan before considering any risks.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in public institutions, as described in a research summary in a central research briefing context.','Managers blamed a single change because complaints rose quickly.','Managers ignored the decline because it was caused by one change.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','The decline in complaints was sudden and easy to explain.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The writer contrasts short-term popularity with long-term reliability during periods of change, as described in a public debate in a online research briefing context.','The writer says popularity and reliability are exactly the same.','The writer discusses reliability without mentioning popularity.','The writer argues that long-term reliability is impossible.','The writer points out a difference between being popular now and being dependable over time.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Although traffic cameras was initially criticized, later evidence showed that it could be useful when applied carefully in small communities, as described in a training program in a evening research briefing context.','Later evidence suggested that traffic cameras, despite early criticism, may have value if used carefully.','The usefulness of traffic cameras was accepted before anyone criticized it.','Later evidence showed that traffic cameras should never be applied.','Early criticism proved that traffic cameras had no value at all.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The report does not claim that renewable energy storage solves every problem; it argues only that it can reduce one specific difficulty when resources are limited, as described in an evaluation report in a summer research briefing context.','The report rejects the idea that renewable energy storage can help in any way.','According to the report, renewable energy storage is not a complete solution but may help with a particular problem.','The report argues that renewable energy storage solves all problems completely.','The report discusses many solutions but never mentions a specific problem.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion under careful supervision, as described in a committee meeting in a advanced research briefing context.','The researchers made a recommendation because the data were complete.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The available data forced the researchers to reject all conclusions.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_44", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
